def build(d):
    d["cast"]="".join(f"<span><b>{n}</b> ({s})</span>" if s else f"<span><b>{n}</b></span>" for n,s in d["cast"])
    d["rows"]="\n".join("<tr>"+"".join(f"<td>{c}</td>" for c in r)+"</tr>" for r in d["rows"])
    d["blocks"]="".join(f'<span class="blk {k}">{t}</span>' for k,t in d["blocks"])
    d["checks"]="".join(f"<li>{c}</li>" for c in d["checks"])
    return TPL % d
